//! Certificate Transparency over certificates captured from live sites on
//! 2026-10-12: www.cloudflare.com (Google Trust Services WE1) and
//! www.wikipedia.org (Let's Encrypt YE2), each carrying two embedded SCTs.
//! The time is fixed so the suite does not depend on the clock; the bundled
//! log list is regenerated by scripts/ct-logs.ts.

use core::time::Duration;

use pki_types::{CertificateDer, ServerName, UnixTime};
use ps_rustcrypto::policy::ct::{evaluate, is_not_logged, not_logged, CtVerifier, Logged};
use rcgen::{BasicConstraints, CertificateParams, CertifiedIssuer, DnType, IsCa, KeyPair};
use rustls::client::danger::ServerCertVerifier;
use rustls::RootCertStore;

const CLOUDFLARE_LEAF: &[u8] = include_bytes!("fixtures/ct/cloudflare-leaf.der");
const CLOUDFLARE_ISSUER: &[u8] = include_bytes!("fixtures/ct/cloudflare-issuer.der");
const WIKIPEDIA_LEAF: &[u8] = include_bytes!("fixtures/ct/wikipedia-leaf.der");
const WIKIPEDIA_ISSUER: &[u8] = include_bytes!("fixtures/ct/wikipedia-issuer.der");

/// 2026-10-12T00:00:00Z.
fn now() -> UnixTime {
    UnixTime::since_unix_epoch(Duration::from_secs(1_791_763_200))
}

/// The first byte of the first embedded SCT signature in a leaf.
fn first_signature(leaf: &[u8]) -> usize {
    let sct_oid = [0x2b, 0x06, 0x01, 0x04, 0x01, 0xd6, 0x79, 0x02, 0x04, 0x02];
    let at = leaf
        .windows(sct_oid.len())
        .position(|window| window == sct_oid)
        .expect("embedded SCT extension");
    // OID, OCTET STRING header, OCTET STRING header, list length, SCT length,
    // then version, log id, timestamp, extensions, algorithms, signature length.
    let mut cursor = at + sct_oid.len();
    for _ in 0..2 {
        let first = leaf[cursor + 1];
        cursor += 2 + if first >= 0x80 {
            usize::from(first & 0x7f)
        } else {
            0
        };
    }
    let extensions = usize::from(u16::from_be_bytes([
        leaf[cursor + 4 + 41],
        leaf[cursor + 4 + 42],
    ]));
    cursor + 4 + 1 + 32 + 8 + 2 + extensions + 2 + 2
}

#[test]
fn cloudflare_embedded_scts_comply() {
    let logged = evaluate(CLOUDFLARE_LEAF, &[CLOUDFLARE_ISSUER], &[], &[], now()).unwrap();
    assert_eq!(
        logged,
        Logged {
            valid: 2,
            operators: 2
        }
    );
}

#[test]
fn wikipedia_embedded_scts_comply() {
    let logged = evaluate(WIKIPEDIA_LEAF, &[WIKIPEDIA_ISSUER], &[], &[], now()).unwrap();
    assert_eq!(
        logged,
        Logged {
            valid: 2,
            operators: 2
        }
    );
}

#[test]
fn the_issuer_is_found_among_intermediates() {
    let logged = evaluate(
        CLOUDFLARE_LEAF,
        &[WIKIPEDIA_ISSUER, CLOUDFLARE_ISSUER],
        &[],
        &[],
        now(),
    )
    .unwrap();
    assert_eq!(logged.valid, 2);
}

#[test]
fn a_wrong_issuer_key_hash_fails_every_sct() {
    let error = evaluate(CLOUDFLARE_LEAF, &[WIKIPEDIA_ISSUER], &[], &[], now()).unwrap_err();
    assert_eq!((error.found, error.valid), (2, 0));
}

#[test]
fn a_tampered_signature_leaves_one_sct_and_fails() {
    let mut leaf = CLOUDFLARE_LEAF.to_vec();
    let at = first_signature(&leaf);
    assert_eq!(leaf[at], 0x30, "signature DER header");
    leaf[at + 10] ^= 0x01;
    let error = evaluate(&leaf, &[CLOUDFLARE_ISSUER], &[], &[], now()).unwrap_err();
    assert_eq!((error.found, error.valid, error.required), (2, 1, 2));
    assert!(error
        .to_string()
        .starts_with("certificate not publicly logged"));
}

#[test]
fn a_tampered_certificate_fails_every_sct() {
    let mut leaf = WIKIPEDIA_LEAF.to_vec();
    // A byte of the serial number, inside the TBS the logs signed.
    leaf[15] ^= 0x01;
    let error = evaluate(&leaf, &[WIKIPEDIA_ISSUER], &[], &[], now()).unwrap_err();
    assert_eq!((error.found, error.valid), (2, 0));
}

#[test]
fn an_sct_from_the_future_does_not_count() {
    // 2026-09-01, before the Cloudflare certificate was logged.
    let early = UnixTime::since_unix_epoch(Duration::from_secs(1_788_220_800));
    let error = evaluate(CLOUDFLARE_LEAF, &[CLOUDFLARE_ISSUER], &[], &[], early).unwrap_err();
    assert_eq!(error.valid, 0);
}

#[test]
fn precertificate_scts_do_not_count_when_delivered() {
    // The same SCT list handed over as if by TLS: signed over the
    // precertificate, so it cannot verify as an X.509 entry.
    let leaf = rcgen_leaf();
    let sct_list = embedded_list(CLOUDFLARE_LEAF);
    let error = evaluate(leaf.as_ref(), &[], &[], sct_list, now()).unwrap_err();
    assert_eq!((error.found, error.valid), (2, 0));
}

#[test]
fn a_certificate_without_scts_is_not_logged() {
    let error = evaluate(rcgen_leaf().as_ref(), &[], &[], &[], now()).unwrap_err();
    assert_eq!((error.found, error.valid), (0, 0));
}

#[test]
fn the_verifier_reports_an_unlogged_chain_readably() {
    let mut params = CertificateParams::new(Vec::new()).unwrap();
    params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
    params
        .distinguished_name
        .push(DnType::CommonName, "CT test root");
    let root = CertifiedIssuer::self_signed(params, KeyPair::generate().unwrap()).unwrap();
    let leaf = CertificateParams::new(vec![String::from("localhost")])
        .unwrap()
        .signed_by(&KeyPair::generate().unwrap(), &root)
        .unwrap();
    let mut roots = RootCertStore::empty();
    roots.add(root.der().clone()).unwrap();
    let verifier = CtVerifier::ecc_only(roots).unwrap();
    let error = verifier
        .verify_server_cert(
            leaf.der(),
            &[],
            &ServerName::try_from("localhost").unwrap(),
            &[],
            UnixTime::now(),
        )
        .unwrap_err();
    assert!(is_not_logged(&error), "{error:?}");
    assert!(not_logged(&error)
        .unwrap()
        .to_string()
        .contains("certificate not publicly logged"));
}

fn rcgen_leaf() -> CertificateDer<'static> {
    let key = KeyPair::generate().unwrap();
    let params = CertificateParams::new(vec![String::from("localhost")]).unwrap();
    params.self_signed(&key).unwrap().der().clone()
}

/// The TLS-encoded SCT list inside a leaf embedded SCT extension.
fn embedded_list(leaf: &[u8]) -> &[u8] {
    let sct_oid = [0x2b, 0x06, 0x01, 0x04, 0x01, 0xd6, 0x79, 0x02, 0x04, 0x02];
    let mut cursor = leaf
        .windows(sct_oid.len())
        .position(|window| window == sct_oid)
        .unwrap()
        + sct_oid.len();
    let mut length = 0;
    for _ in 0..2 {
        let first = leaf[cursor + 1];
        let extra = if first >= 0x80 {
            usize::from(first & 0x7f)
        } else {
            0
        };
        length = if extra == 0 {
            usize::from(first)
        } else {
            leaf[cursor + 2..cursor + 2 + extra]
                .iter()
                .fold(0, |length, byte| (length << 8) | usize::from(*byte))
        };
        cursor += 2 + extra;
    }
    &leaf[cursor..cursor + length]
}
